    ): Note = c.update(id, data.toMap(), expand = expand, fields = fields)

    suspend fun delete(id: String) = c.delete(id)

    /** Compiles a typed filter expression to a server filter string. */
    fun filter(fn: (NoteFields) -> Expr): String = fn(NoteFields()).compile()

    fun fileUrl(
        record: Note,
        field: NoteFileField,
        download: Boolean = false,
        thumb: String? = null,
        token: String? = null,
    ): String {
        val filename =
            when (field) {
                NoteFileField.ATTACHMENT -> record.attachment
            }
        return c.fileUrl(
            ZbRecord(
                buildJsonObject {
                    put("id", record.id)
                    put("collectionName", "notes")
                },
            ),
            filename,
            download = download,
            thumb = thumb,
            token = token,
        )
    }
}

enum class NoteFileField(
    val wire: String,
) {
    ATTACHMENT("attachment"),
}

