class ZbClient(
    val raw: ZigbaseClient,
    val owned: Boolean = false,
) : AutoCloseable {
    val profiles: ProfilesService by lazy { ProfilesService(raw) }
    val tags: TagsService by lazy { TagsService(raw) }
    val photos: PhotosService by lazy { PhotosService(raw) }
    val privatePhotos: PrivatePhotosService by lazy { PrivatePhotosService(raw) }
    val messages: MessagesService by lazy { MessagesService(raw) }
    val winks: WinksService by lazy { WinksService(raw) }
    val subscriptions: SubscriptionsService by lazy { SubscriptionsService(raw) }
    val notes: NotesService by lazy { NotesService(raw) }

    val profilesRealtime: ProfilesRealtime by lazy { ProfilesRealtime(raw) }
    val tagsRealtime: TagsRealtime by lazy { TagsRealtime(raw) }
    val photosRealtime: PhotosRealtime by lazy { PhotosRealtime(raw) }
    val privatePhotosRealtime: PrivatePhotosRealtime by lazy { PrivatePhotosRealtime(raw) }
    val messagesRealtime: MessagesRealtime by lazy { MessagesRealtime(raw) }
    val winksRealtime: WinksRealtime by lazy { WinksRealtime(raw) }
    val subscriptionsRealtime: SubscriptionsRealtime by lazy { SubscriptionsRealtime(raw) }
    val notesRealtime: NotesRealtime by lazy { NotesRealtime(raw) }

    val authStore: AuthStore get() = raw.authStore

    suspend fun send(
        method: HttpMethod,
        path: String,
        query: Map<String, String>? = null,
        body: Map<String, Any?>? = null,
        headers: Map<String, String>? = null,
    ): JsonElement? = raw.send(method, path, query = query, body = body, headers = headers)

    override fun close() {
        if (owned) raw.close()
    }
}

fun createClient(
    url: String,
    authStore: AuthStore = MemoryAuthStore(),
    autoRefresh: Boolean = false,
    authCollection: String? = "profiles",
    accountId: String? = null,
    lang: String? = null,
    maxRetries: Int = 3,
    httpClient: HttpClient? = null,
    onRealtimeError: ((String) -> Unit)? = null,
): ZbClient =
    ZbClient(
        ZigbaseClient(
            url,
            authStore = authStore,
            autoRefresh = autoRefresh,
            authCollection = authCollection,
            accountId = accountId,
            lang = lang,
            maxRetries = maxRetries,
            httpClient = httpClient,
            onRealtimeError = onRealtimeError,
        ),
        owned = true,
    )
